class PhoneNumber:
    def __init__(self, number):
        if any(c.isalpha() for c in number):
            raise ValueError("letters not permitted")
        if any(not c.isdigit() and not c.isspace() and c not in "-().+" for c in number):
            raise ValueError("punctuations not permitted")

        cleaned = "".join(c for c in number if c.isdigit())

        if len(cleaned) < 10:
            raise ValueError("must not be fewer than 10 digits")
        if len(cleaned) > 11:
            raise ValueError("must not be greater than 11 digits")
        if len(cleaned) == 11 and not cleaned.startswith("1"):
            raise ValueError("11 digits must start with 1")

        if cleaned.startswith("1"):
            cleaned = cleaned[1:]

        self.number = cleaned

    @property
    def area_code(self):
        return self.number[:3]

    def pretty(self):
        return "({})-{}-{}".format(self.number[:3], self.number[3:6], self.number[6:])

